import math

def min_spots(n, H):
    def can_build(m):
        total = 0
        prev = H
        for i in range(m):
            curr = min(prev + 1, n - total + m - i - 1)
            if curr < prev - 1:
                return False
            total += curr
            prev = curr
        return total >= n

    left, right = 1, math.ceil((math.sqrt(8*n + 1) - 1) / 2) + 1
    while left < right:
        mid = (left + right) // 2
        if can_build(mid):
            right = mid
        else:
            left = mid + 1
    return left

