def min_spots_for_castle(n: int, H: int) -> int:
    if n <= H:
        return 1

    left = 1
    right = n

    while left < right:
        mid = (left + right) // 2
        height = (n + mid - 1) // mid

        if height <= H and abs(height - (height - 1)) <= 1:
